INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @media_3,'_wp_attached_file','2026/09/navar-city-generated/نوار-تیپ-20-سانتی-بفروییه-یزد-navar-tip-20cm-جزئیات-فنی.webp' WHERE @created_post=1 AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@media_3 AND meta_key='_wp_attached_file');
INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @media_3,'_wp_attachment_image_alt','فیلتر و تنظیم فشار سیستم آبیاری قطره‌ای در بفروییه' WHERE @created_post=1 AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@media_3 AND meta_key='_wp_attachment_image_alt');
INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @post_id,'_thumbnail_id',@media_1 WHERE @created_post=1 AND @media_1 IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@post_id AND meta_key='_thumbnail_id');
